import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useUsuarioStore } from "../store/Usuario";

export const useValidarSesion = () => {
    const { token, usuario } = useUsuarioStore();
    const [storeCargado, setStoreCargado] = useState(false);
    const navegar = useNavigate();

    useEffect(() => {
        // Espera a que Zustand termine de hidratar el store
        const timeout = setTimeout(() => {
            setStoreCargado(true); // forzamos carga aunque Zustand no dispare nada
        }, 200); // 0.2 segundos de margen, suficiente

        const unsubscribe = useUsuarioStore.persist.onFinishHydration(() => {
            clearTimeout(timeout);
            setStoreCargado(true);
        });

        return () => {
            clearTimeout(timeout);
            unsubscribe();
        };
    }, []);

    useEffect(() => {
        if (storeCargado && (!token || !usuario)) {
            alert("No puede acceder. Inicie sesión.");
            navegar("/inicioSesion");
        }
    }, [storeCargado, token, usuario, navegar]);

    return { storeCargado, token, usuario };
};
